public class Main {
    static int canCompleteCircuitBrute(int[] gas, int[] cost) {
        int n = gas.length;
        for (int start = 0; start < n; start++) {               // try every starting station
            int tank = 0;
            boolean valid = true;
            for (int i = 0; i < n; i++) {
                int station = (start + i) % n;
                tank += gas[station] - cost[station];
                if (tank < 0) { valid = false; break; }
            }
            if (valid) return start;
        }
        return -1;
    }
}

